@section('content')<div x-data="periodsManager({{ Illuminate\Support\Js::from($periods) }})" class="grid gap-4 lg:grid-cols-2"><template x-for="(p,i) in rows" :key="p.id"><article class="rounded-xl border bg-white p-5"><div class="flex justify-between"><h2 class="text-lg font-semibold" x-text="p.period_label"></h2><span x-text="p.status" class="rounded-full bg-gray-100 px-3 py-1 text-sm"></span></div><p class="mt-2 text-sm text-gray-700" x-text="`${p.cutoff_start} – ${p.cutoff_end} · Pay date ${p.pay_date}`"></p><p class="mt-2 text-sm">Employees: <span x-text="p.records.length"></span></p><div class="mt-4 grid grid-cols-3 gap-2 text-sm"><div>Gross<br><b x-text="money(p.totals.gross)"></b></div><div>Deductions<br><b x-text="money(p.totals.deductions)"></b></div><div>Net<br><b x-text="money(p.totals.net)"></b></div></div><div class="mt-4 flex gap-2"><button x-show="p.status==='Draft'" @click="p.status='Under Review';$dispatch('show-toast',{message:'Payroll review started.'})" class="rounded bg-[#0b1f33] px-4 py-2 text-sm text-white">Start Review</button><button x-show="p.status==='Under Review'" @click="selected=p;confirmOpen=true" class="rounded bg-emerald-700 px-4 py-2 text-sm text-white">Finalize</button><button x-show="p.status==='Finalized'" disabled title="This period is finalized" class="rounded bg-gray-200 px-4 py-2 text-sm">Finalized</button><a class="rounded border px-4 py-2 text-sm" :href="`/payroll/records/${p.id}`">View records</a></div></article></template><div x-show="confirmOpen" x-cloak class="fixed inset-0 z-40 grid place-items-center bg-black/50 p-4"><div x-trap.inert.noscroll="confirmOpen" role="dialog" aria-modal="true" class="w-full max-w-md rounded-xl bg-white p-6"><h3 class="text-lg font-semibold">Finalize payroll period?</h3><p class="my-3 text-sm">This will mark <span x-text="selected?.period_label"></span> as finalized.</p><div class="flex justify-end gap-2"><button @click="confirmOpen=false" class="rounded border px-4 py-2">Cancel</button><button @click="selected.status='Finalized';confirmOpen=false;$dispatch('show-toast',{message:'Payroll period finalized.'})" class="rounded bg-[#0b1f33] px-4 py-2 text-white">Confirm</button></div></div></div></div><script>function periodsManager(rows){return {rows,confirmOpen:false,selected:null,money(v){return '₱'+Number(v).toLocaleString('en-PH',{minimumFractionDigits:2})}}}</script>@endsection
